(function(){
const D=window.SHAFRAN_DATA, saved=JSON.parse(localStorage.getItem('shafran-control-v3')||'{}');
const state={tasks:saved.tasks||D.tasks,orders:saved.orders||{},integrations:saved.integrations||{},prices:saved.prices||{}};
const view=document.getElementById('view'),crumbs=document.getElementById('crumbs'),drawer=document.getElementById('drawer'),drawerBody=document.getElementById('drawerBody'),overlay=document.getElementById('overlay'),modal=document.getElementById('modal'),modalBody=document.getElementById('modalBody');
const routes={dashboard:'Пульт сети',restaurants:'Рестораны',stock:'Закуп и склад',menu:'Меню и калькуляции',finance:'Финансы',marketing:'Маркетинг / SMM',tasks:'Задачи и решения',integrations:'Интеграции'};
const pos=[[15,64],[20,56],[26,66],[31,51],[35,71],[39,38],[42,60],[47,48],[52,72],[56,35],[61,56],[65,29],[69,68],[73,45],[77,61],[82,39],[86,53],[89,35],[58,63],[33,39],[23,43],[70,33]];
const fmt=n=>new Intl.NumberFormat('ru-RU').format(Math.round(n)); const money=n=>fmt(n)+' ₸'; const million=n=>n.toFixed(2).replace('.',',')+' млн ₸';
function save(){localStorage.setItem('shafran-control-v3',JSON.stringify(state));badges()}
function badges(){const n=state.tasks.filter(x=>x.status!=='done').length;document.getElementById('taskBadge').textContent=n;document.getElementById('topTaskBadge').textContent=n}
function route(){const q=new URLSearchParams(location.search);return{s:q.get('s')||'dashboard',id:q.get('id'),tab:q.get('tab')||'overview'}}
function go(s,id,tab){const u=new URL(location.href);u.search='';u.searchParams.set('s',s);if(id)u.searchParams.set('id',id);if(tab)u.searchParams.set('tab',tab);history.pushState(null,'',u);render();window.scrollTo({top:0,behavior:'smooth'})}
function pageHead(kicker,title,text,actions=''){return `<div class="page-head"><div><span class="kicker">${kicker}</span><h1>${title}</h1><p>${text}</p></div><div class="head-actions">${actions}</div></div>`}
function statusTag(s){return `<span class="status-tag ${s}">${s==='ok'?'Стабильно':s==='warn'?'Внимание':'Риск'}</span>`}
function spark(vals=[42,55,48,67,61,82,74,88,100]){return `<div class="spark">${vals.map(v=>`<i style="height:${v}%"></i>`).join('')}</div>`}
function metric(label,val,note,cls='',extra=''){return `<article class="metric ${cls}"><small>${label}</small><b>${val}</b><span class="${note.includes('↑')?'up':note.includes('↓')?'down':''}">${note}</span>${extra}</article>`}
function restaurantTable(limit){const rs=limit?D.restaurants.slice(0,limit):D.restaurants;return `<article class="panel"><div class="panel-head"><div><span class="kicker">СРАВНЕНИЕ ТОЧЕК</span><h2>${limit?'Точки, требующие внимания':'Все рестораны сети'}</h2></div>${limit?'<button class="btn" data-nav="restaurants">Все 22 точки →</button>':'<button class="btn" data-action="export">Экспорт XLSX</button>'}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ресторан</th><th>Выручка сегодня</th><th>План</th><th>Фудкост</th><th>Средний чек</th><th>Гости</th><th>Состояние</th></tr></thead><tbody>${rs.map(r=>`<tr class="clickable" data-open="restaurant" data-id="${r.id}"><td><div class="entity"><i class="${r.status}"></i><b>${r.name}</b><small>${r.city} · ${r.manager}</small></div></td><td>${million(r.revenue)}</td><td><div class="bar"><i style="width:${Math.min(100,r.plan)}%"></i><span>${r.plan}%</span></div></td><td class="${r.food>33?'bad':r.food>30?'warn-text':'good'}">${r.food}%</td><td>${money(r.check)}</td><td>${r.guests}</td><td>${statusTag(r.status)}</td></tr>`).join('')}</tbody></table></div></article>`}
function renderDashboard(){const risks=D.restaurants.filter(r=>r.status!=='ok');return pageHead('AI COMMAND CENTER','Сеть сегодня','Решения по 22 ресторанам — от выручки до конкретного действия.','<button class="btn" data-action="period">Период: сегодня ⌄</button><button class="btn-dark" data-action="new-task">+ Поставить задачу</button>')+`<section class="metrics">${metric('Выручка сегодня','54,8 млн ₸','↑ 8,4% к прошлому понедельнику','dark',spark())}${metric('Средний чек','12 460 ₸','↑ 640 ₸ за 7 дней')}${metric('Средний фудкост','30,7%','↓ цель ≤ 30%','',`<div class="progress"><i style="width:69%;background:var(--red)"></i></div>`)}${metric('Гости / брони','4 397','↑ 6,1% · 312 броней')}</section><section class="grid"><article class="panel network-panel"><div class="panel-head"><div><span class="kicker">СЕТЬ В РЕАЛЬНОМ ВРЕМЕНИ</span><h2>Карта операционного здоровья</h2></div><span class="tag">● LIVE · 2 мин</span></div><div class="map">${D.restaurants.map((r,i)=>`<button class="map-dot ${r.status}" style="left:${pos[i][0]}%;top:${pos[i][1]}%" title="${r.name}" data-open="restaurant" data-id="${r.id}"></button>`).join('')}<div class="legend"><span><i style="background:var(--green)"></i>11 стабильно</span><span><i style="background:var(--amber)"></i>7 внимание</span><span><i style="background:var(--red)"></i>4 риска</span></div></div></article><article class="panel"><div class="panel-head"><div><span class="kicker">AI-КОНТРОЛЬ</span><h2>Требует решения</h2></div><span class="status-tag risk">3 сигнала</span></div><div class="ai-list"><div class="signal risk"><i></i><div><b>Фудкост выше нормы</b><p>Шафран · Арбат — 34,8%. AI нашёл рост потерь по мясной группе и расхождение списаний.</p><button class="link-btn" data-open="restaurant" data-id="r3" data-tab="stock">Провалиться в причину →</button></div><span>01</span></div><div class="signal"><i></i><div><b>Лосось закончится через 9 часов</b><p>Туран — дефицит 13 кг до поставки. Есть доступный остаток в MEGA.</p><button class="link-btn" data-open="stock" data-id="s1">Открыть товар и прогноз →</button></div><span>02</span></div><div class="signal"><i></i><div><b>Реклама дорожает</b><p>«Семейный ужин»: стоимость подтверждённой брони выросла на 27%.</p><button class="link-btn" data-open="campaign" data-id="c1">Разобрать кампанию →</button></div><span>03</span></div></div></article></section>${restaurantTable(6)}<section class="cards" style="margin-top:11px"><article class="card"><span class="kicker">ДЕНЬГИ</span><h3>P&L сети</h3><p>Выручка, валовая прибыль, расходы и EBITDA с проваливанием до ресторана и операции.</p><button class="btn" data-nav="finance">Открыть финансы →</button></article><article class="card"><span class="kicker">ПРОДУКТ</span><h3>Меню-инжиниринг</h3><p>Техкарты из iiko, фактическая себестоимость и AI-сценарии цены/выхода.</p><button class="btn" data-nav="menu">Открыть меню →</button></article><article class="card"><span class="kicker">РОСТ</span><h3>Маркетинг → чек</h3><p>Канал, кампания, бронь, визит и чек — единая атрибуция эффективности.</p><button class="btn" data-nav="marketing">Открыть маркетинг →</button></article></section>`}
function renderRestaurants(){return pageHead('22 ТОЧКИ · КАЗАХСТАН','Рестораны','Каждая точка — отдельный цифровой P&L, склад, команда и клиентский опыт.','<button class="btn" data-action="compare">Сравнить точки</button><button class="btn-dark" data-action="new-task">+ Задача ресторану</button>')+`<section class="metrics">${metric('Выполняют план','12 / 22','↑ 3 точки за неделю')}${metric('В зоне внимания','7','фудкост / склад / сервис')}${metric('Критические','4','↓ требуются решения')}${metric('EBITDA сети','14,8%','↑ 1,6 п.п. к июлю')}</section>${restaurantTable()}`}
function tabs(items,active){return `<div class="tabs">${items.map(x=>`<button class="${active===x[0]?'active':''}" data-tab="${x[0]}">${x[1]}</button>`).join('')}</div>`}
function restaurantDetail(r,tab){const tabNames=[['overview','Обзор'],['sales','Продажи'],['stock','Склад'],['team','Команда'],['reviews','Отзывы'],['finance','P&L']];let body='';if(tab==='overview')body=`<section class="metrics">${metric('Выручка сегодня',million(r.revenue),'↑ 6,8% к плану','dark',spark([45,52,59,48,70,81,77,92]))}${metric('Средний чек',money(r.check),'↑ 4,2% за 7 дней')}${metric('Фудкост',r.food+'%',r.food>30?'↓ выше целевого 30%':'↑ в норме')}${metric('Гости',r.guests,'↑ 18 к прошлой неделе')}</section><section class="grid equal"><article class="panel"><span class="kicker">AI-РАЗБОР</span><h2>Что влияет на результат</h2><div class="signal ${r.food>33?'risk':''}"><i></i><div><b>${r.food>33?'Списания мяса выше модели':'Продажи вечернего меню растут'}</b><p>${r.food>33?'Факт на 8,4 кг выше расчётного расхода. Проверьте возвраты и порционирование.':'Доля чека после 18:00 выросла на 12% благодаря семейным сетам.'}</p><button class="link-btn" data-tab="${r.food>33?'stock':'sales'}">Открыть детализацию →</button></div><span>AI</span></div><div class="signal"><i></i><div><b>Скорость кухни: 18:42</b><p>На 2:10 быстрее средней сети. Пик задержек — с 20:00 до 20:30.</p><button class="link-btn" data-action="create-restaurant-task" data-id="${r.id}">Поставить задачу →</button></div></div></article><article class="panel"><span class="kicker">СЕГОДНЯ</span><h2>Хронология точки</h2><div class="timeline"><div class="timeline-item"><b>11:48 · Закрыт стоп-лист</b><span>Лосось перемещён из соседней точки · 18 кг</span></div><div class="timeline-item"><b>10:31 · Планёрка завершена</b><span>12 сотрудников подтвердили задачи смены</span></div><div class="timeline-item"><b>09:15 · Открыта смена</b><span>Касса iiko · расхождений нет</span></div><div class="timeline-item"><b>08:40 · Приёмка поставки</b><span>Qazaq Meat · 124 кг · 1 замечание</span></div></div></article></section>`;else if(tab==='sales')body=`<section class="metrics">${metric('Чеки','418','↑ 7,2%')}${metric('Средний чек',money(r.check),'↑ 4,2%')}${metric('Брони','31','24 подтверждены')}${metric('Повторные гости','38%','↑ 3 п.п.')}</section><article class="panel"><div class="panel-head"><div><span class="kicker">ПО ЧАСАМ</span><h2>Выручка и загрузка зала</h2></div><span class="tag">Данные iiko</span></div><div class="chart">${[22,31,45,62,58,71,86,94,78,56,40,29].map((x,i)=>`<div><i style="height:${x}%"></i><span>${11+i}:00</span></div>`).join('')}</div></article>`;else if(tab==='stock')body=`<section class="grid equal"><article class="panel"><div class="panel-head"><div><span class="kicker">ОСТАТКИ ТОЧКИ</span><h2>Риски и отклонения</h2></div><button class="btn" data-action="inventory" data-id="${r.id}">Инвентаризация</button></div>${D.stock.slice(0,6).map((x,i)=>`<div class="stock-row"><span class="stock-icon">${i+1}</span><div><b class="click" data-open="stock" data-id="${x.id}">${x.name}</b><small>${x.supplier}</small></div><div><small>Остаток</small><b>${Math.max(3,Math.round(x.balance/22*(.7+(r.id.slice(1)%5)/10)))} ${x.unit}</b></div><div><small>Отклонение</small><b class="${i<2?'bad':'good'}">${i<2?'-'+(8+i*4):'+'+(3+i)}%</b></div><button class="arrow" data-open="stock" data-id="${x.id}">→</button></div>`).join('')}</article><article class="panel"><span class="kicker">ДВИЖЕНИЯ</span><h2>Последние операции</h2><div class="timeline"><div class="timeline-item"><b>Списание · говядина 8,4 кг</b><span>Производство · смена №1824 · 11:36</span></div><div class="timeline-item"><b>Перемещение · лосось 18 кг</b><span>Из ${D.restaurants[3].name} · 10:52</span></div><div class="timeline-item"><b>Приход · овощи 146 кг</b><span>Green Market · накладная 00841 · 08:40</span></div><div class="timeline-item"><b>Корректировка · рис −3 кг</b><span>Инвентаризация · Алия С. · вчера</span></div></div></article></section>`;else if(tab==='team')body=`<section class="metrics">${metric('В смене','31 сотрудник','28 на месте · 3 в пути')}${metric('ФОТ / выручка','18,7%','↑ цель ≤ 20%')}${metric('Опоздания','2','↓ на 3 к прошлой неделе')}${metric('eNPS','62','↑ +7 за квартал')}</section><article class="panel"><div class="panel-head"><div><span class="kicker">СМЕНА</span><h2>Команда ресторана</h2></div><button class="btn-dark" data-action="new-task">+ Задача сотруднику</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Смена</th><th>KPI</th><th>Статус</th></tr></thead><tbody>${['Управляющий','Шеф-повар','Су-шеф','Кассир','Официант','Кладовщик'].map((x,i)=>`<tr><td><b>${['Алия С.','Марат Ж.','Ерлан К.','Дана А.','Асем М.','Руслан Т.'][i]}</b></td><td>${x}</td><td>${i<3?'08:00–20:00':'11:00–23:00'}</td><td class="good">${91+i}%</td><td>${i===4?statusTag('warn'):statusTag('ok')}</td></tr>`).join('')}</tbody></table></div></article>`;else if(tab==='reviews')body=`<section class="metrics">${metric('Рейтинг','4,72 / 5','↑ 0,08 за месяц')}${metric('NPS','68','↑ +11 за квартал')}${metric('Отзывов','184','92% обработано')}${metric('Среднее время ответа','18 мин','↓ быстрее на 6 мин')}</section><section class="grid equal"><article class="panel"><span class="kicker">ОТЗЫВЫ</span><h2>Последние обращения</h2>${[['5','Отличный плов и быстрый сервис','2GIS · 24 мин'],['3','Долго ждали десерт','Google · 1 ч'],['5','Лучший семейный ресторан','Instagram · 3 ч']].map(x=>`<div class="signal"><i></i><div><b>${'★'.repeat(+x[0])}</b><p>${x[1]}</p><button class="link-btn" data-action="reply-review">Ответить →</button></div><span>${x[2]}</span></div>`).join('')}</article><article class="panel"><span class="kicker">ТЕМЫ</span><h2>Что говорят гости</h2><div class="compare"><div><small>Кухня</small><b>+84</b></div><div><small>Сервис</small><b>+61</b></div><div><small>Скорость</small><b>+48</b></div><div><small>Чистота</small><b>+77</b></div></div><div class="recommendation"><b>AI-вывод</b><p>Основная точка роста — скорость подачи десертов после 20:00. Среднее ожидание 16 минут против 11 по сети.</p></div></article></section>`;else body=restaurantFinance(r);return `<section class="detail-hero"><div><span class="kicker">${r.city} · RESTAURANT ID ${r.id.toUpperCase()}</span><h1>${r.name}</h1><p>Управляющий: ${r.manager} · ${r.staff} сотрудников · последняя синхронизация iiko 2 мин назад</p></div><div class="hero-kpis"><div><small>ПЛАН</small><b>${r.plan}%</b></div><div><small>ФУДКОСТ</small><b>${r.food}%</b></div><div><small>СТАТУС</small><b>${r.status==='ok'?'Стабильно':r.status==='warn'?'Внимание':'Риск'}</b></div></div></section>${tabs(tabNames,tab)}${body}`}
function restaurantFinance(r){return `<section class="metrics">${metric('Выручка MTD',million(r.revenue*22),'↑ 9,1%')}${metric('Валовая прибыль',million(r.revenue*9.4),'42,7%')}${metric('OPEX',million(r.revenue*6.1),'↑ 2,3% к бюджету')}${metric('EBITDA',million(r.revenue*3.3),'14,9%')}</section><section class="grid equal"><article class="panel"><span class="kicker">P&L РЕСТОРАНА</span><h2>Расшифровка результата</h2><div class="table-wrap"><table class="data-table"><tbody>${[['Выручка',r.revenue*22,100],['Себестоимость',-r.revenue*6.8,31],['ФОТ',-r.revenue*4.1,19],['Аренда',-r.revenue*1.8,8],['Маркетинг',-r.revenue*.7,3],['Прочие расходы',-r.revenue*1.3,6],['EBITDA',r.revenue*3.3,15]].map((x,i)=>`<tr class="clickable" data-action="finance-drill" data-label="${x[0]}"><td><b>${x[0]}</b></td><td class="${x[1]<0?'bad':'good'}">${million(Math.abs(x[1]))}</td><td>${x[2]}%</td><td>→</td></tr>`).join('')}</tbody></table></div></article><article class="panel"><span class="kicker">ДИНАМИКА</span><h2>EBITDA по неделям</h2><div class="chart">${[44,52,48,67,59,72,81,76,88,92,85,96].map((x,i)=>`<div><i style="height:${x}%"></i><span>${i+1}</span></div>`).join('')}</div></article></section>`}
function renderStock(){return pageHead('SUPPLY CHAIN','Закуп и склад','Остатки 22 точек, центральный склад, поставщики, прогноз и автозаявки.','<button class="btn" data-action="transfers">Перемещения</button><button class="btn-copper" data-action="new-order">+ Заявка поставщику</button>')+`<section class="metrics">${metric('Запасы сети','186,4 млн ₸','↓ 4,1% без потери доступности')}${metric('Риск стоп-листа','4 позиции','3 заявки подготовлены')}${metric('Потери / списания','1,8%','↓ 0,4 п.п. за месяц')}${metric('Экономия AI','6,2 млн ₸','↑ за 30 дней')}</section><section class="grid equal"><article class="panel"><div class="panel-head"><div><span class="kicker">AI-ПЛАН ЗАКУПА</span><h2>Ближайшие решения</h2></div><span class="tag">7 дней · 12,4 млн ₸</span></div>${D.stock.slice(0,4).map((x,i)=>stockRow(x,i)).join('')}</article><article class="panel"><span class="kicker">ПОСТАВЩИКИ</span><h2>Качество поставок</h2><div class="compare"><div><small>OTIF</small><b>94,2%</b></div><div><small>Отклонение цены</small><b>+1,8%</b></div><div><small>Брак</small><b>0,7%</b></div><div><small>Поставщиков</small><b>38</b></div></div><div class="timeline" style="margin-top:18px"><div class="timeline-item"><b>Ocean Fish KZ · задержка 2 ч</b><span>Поставка лосося · сегодня 15:00</span></div><div class="timeline-item"><b>Qazaq Meat · цена +4%</b><span>AI предлагает запросить альтернативу</span></div><div class="timeline-item"><b>Green Market · без замечаний</b><span>OTIF 99% за 30 дней</span></div></div></article></section><article class="panel"><div class="panel-head"><div><span class="kicker">НОМЕНКЛАТУРА</span><h2>Остатки и прогноз потребности</h2></div><div class="filters"><button class="active">Все</button><button>Мясо</button><button>Овощи</button><button>Бакалея</button></div></div>${D.stock.map((x,i)=>stockRow(x,i)).join('')}</article>`}
function stockRow(x,i){return `<div class="stock-row"><span class="stock-icon">${String(i+1).padStart(2,'0')}</span><div><b class="click" data-open="stock" data-id="${x.id}">${x.name}</b><small>${x.cat} · ${x.supplier}</small></div><div><small>Остаток сети</small><b>${fmt(x.balance)} ${x.unit}</b></div><div><small>Хватит на</small><b class="${x.days<1?'bad':x.days<3?'warn-text':'good'}">${x.days} дн.</b></div><button class="arrow" data-open="stock" data-id="${x.id}">→</button></div>`}
function stockDetail(x){const approved=state.orders[x.id];return `<section class="detail-hero"><div><span class="kicker">${x.cat} · SKU ${x.id.toUpperCase()}</span><h1>${x.name}</h1><p>${x.supplier} · базовая единица: ${x.unit} · данные по 22 ресторанам</p></div><div class="hero-kpis"><div><small>ОСТАТОК</small><b>${fmt(x.balance)} ${x.unit}</b></div><div><small>ХВАТИТ НА</small><b>${x.days} дня</b></div><div><small>ЦЕНА</small><b>${money(x.price)}</b></div></div></section>${tabs([['overview','Прогноз'],['locations','По ресторанам'],['supplier','Поставщик'],['moves','Движения']],route().tab)}${route().tab==='locations'?stockLocations(x):route().tab==='supplier'?stockSupplier(x):route().tab==='moves'?stockMoves(x):`<section class="grid equal"><article class="panel"><span class="kicker">AI-ПРОГНОЗ</span><h2>${x.days<2?'Дефицит до поставки':'Запас в пределах нормы'}</h2><div class="calc-grid"><div><small>Потребность 7 дней</small><b>${fmt(x.min)} ${x.unit}</b></div><div><small>Текущий остаток</small><b>${fmt(x.balance)} ${x.unit}</b></div><div><small>${x.balance<x.min?'К заказу':'Резерв'}</small><b class="${x.balance<x.min?'bad':'good'}">${fmt(Math.abs(x.min-x.balance))} ${x.unit}</b></div></div><div class="recommendation"><b>Рекомендация SHAFRAN AI</b><p>${x.balance<x.min?`Заказать ${fmt(x.min-x.balance)} ${x.unit} у ${x.supplier}. Учитывая брони и продажи по дням недели, запас будет исчерпан через ${x.days} дня.`:'Новый заказ не требуется. Перераспределите излишек между точками с высоким прогнозом продаж.'}</p><button class="${approved?'btn':'btn-copper'}" data-action="approve-order" data-id="${x.id}">${approved?'✓ Заявка согласована':'Согласовать заявку'}</button> <button class="btn" data-action="transfer-item" data-id="${x.id}">Переместить между точками</button></div></article><article class="panel"><span class="kicker">ЦЕНА И ПОТРЕБЛЕНИЕ</span><h2>Динамика за 12 недель</h2><div class="chart">${[62,59,67,71,68,77,74,82,79,91,86,96].map((v,i)=>`<div><i style="height:${v}%"></i><span>${i+1}</span></div>`).join('')}</div><p class="explain">Закупочная цена изменилась на <b class="${x.delta>5?'bad':'good'}">${x.delta>0?'+':''}${x.delta}%</b>. Влияние на фудкост блюд рассчитано автоматически.</p></article></section>`}`}
function stockLocations(x){return `<article class="panel"><span class="kicker">РАСПРЕДЕЛЕНИЕ</span><h2>${x.name} · остатки по ресторанам</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Ресторан</th><th>Факт</th><th>Потребность 3 дня</th><th>Отклонение</th><th>Действие</th></tr></thead><tbody>${D.restaurants.map((r,i)=>{const b=Math.max(1,Math.round(x.balance/22*(.55+(i%7)/10))),need=Math.round(x.min/22*(.8+(i%5)/10));return `<tr class="clickable" data-open="restaurant" data-id="${r.id}" data-tab="stock"><td><b>${r.name}</b><br><small>${r.city}</small></td><td>${b} ${x.unit}</td><td>${need} ${x.unit}</td><td class="${b<need?'bad':'good'}">${b<need?'-':'+'}${Math.abs(b-need)} ${x.unit}</td><td><button class="link-btn" data-action="transfer-item" data-id="${x.id}">Переместить</button></td></tr>`}).join('')}</tbody></table></div></article>`}
function stockSupplier(x){return `<section class="grid equal"><article class="panel"><span class="kicker">КОНТРАГЕНТ</span><h2>${x.supplier}</h2><div class="compare"><div><small>OTIF</small><b>96,4%</b></div><div><small>Качество</small><b>98,1%</b></div><div><small>Средняя цена</small><b>${money(x.price)}</b></div><div><small>Отсрочка</small><b>14 дней</b></div></div><div class="recommendation"><b>AI-оценка: 8,7 / 10</b><p>Надёжный поставщик. Цена выше медианы рынка на 2,1%, но меньше брака и стабильнее сроки.</p><button class="btn" data-action="supplier-message">Написать поставщику</button></div></article><article class="panel"><span class="kicker">АЛЬТЕРНАТИВЫ</span><h2>Сравнение предложений</h2>${['Qazaq Supply','Fresh Trade','Premium Food'].map((n,i)=>`<div class="stock-row"><span class="stock-icon">${i+1}</span><div><b>${n}</b><small>Доставка ${1+i} день</small></div><div><small>Цена</small><b>${money(x.price*(.96+i*.03))}</b></div><div><small>Рейтинг</small><b>${9-i*.4}</b></div><button class="arrow" data-action="request-quote">→</button></div>`).join('')}</article></section>`}
function stockMoves(x){return `<article class="panel"><div class="panel-head"><div><span class="kicker">ЖУРНАЛ</span><h2>Движения: ${x.name}</h2></div><button class="btn" data-action="export">Экспорт</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Операция</th><th>Откуда / куда</th><th>Количество</th><th>Документ</th><th>Ответственный</th></tr></thead><tbody>${[['Сегодня 10:52','Перемещение','MEGA → Туран','18 '+x.unit,'ПМ-01842','Алия С.'],['Сегодня 08:40','Приход','Поставщик → Арбат','124 '+x.unit,'НК-00841','Руслан Т.'],['Вчера 22:31','Списание','Арбат → производство','−8,4 '+x.unit,'СМ-1824','Марат Ж.'],['Вчера 18:12','Возврат','Достык → поставщик','−4 '+x.unit,'ВЗ-0041','Данияр К.']].map(a=>`<tr><td>${a[0]}</td><td><b>${a[1]}</b></td><td>${a[2]}</td><td>${a[3]}</td><td>${a[4]}</td><td>${a[5]}</td></tr>`).join('')}</tbody></table></div></article>`}
function renderMenu(){return pageHead('MENU ENGINEERING','Меню и калькуляции','Фактическая себестоимость из закупочных цен, продажи из iiko и решения по марже.','<button class="btn" data-action="sync-iiko">Синхронизировать iiko</button><button class="btn-dark" data-action="new-dish">+ Новая техкарта</button>')+`<section class="metrics">${metric('Продажи блюд MTD','184 320','↑ 8,1%')}${metric('Средняя маржа','67,4%','↑ 1,2 п.п.')}${metric('Требуют решения','3 блюда','сырьё / цена / выход')}${metric('Эффект рекомендаций','4,8 млн ₸','↑ прогноз в месяц')}</section><section class="cards">${D.dishes.map(d=>`<article class="card"><div class="card-top"><span class="kicker">${d.cat}</span><span class="status-tag ${d.label==='Пересмотреть'?'risk':'ok'}">${d.label}</span></div><h3>${d.name}</h3><p>${d.ingredients.length} ингредиента · техкарта синхронизирована с iiko</p><div class="card-metrics"><div><small>Цена</small><b>${money(state.prices[d.id]||d.price)}</b></div><div><small>Себестоимость</small><b>${money(d.cost)}</b></div><div><small>Маржа</small><b class="${(d.price-d.cost)/d.price<.6?'bad':'good'}">${Math.round((d.price-d.cost)/d.price*100)}%</b></div><div><small>Продажи MTD</small><b>${fmt(d.sales)}</b></div></div><button class="btn" data-open="dish" data-id="${d.id}">Открыть техкарту →</button></article>`).join('')}</section>`}
function dishDetail(d){const price=state.prices[d.id]||d.price,margin=Math.round((price-d.cost)/price*100);return `<section class="detail-hero"><div><span class="kicker">${d.cat} · ТЕХКАРТА ${d.id.toUpperCase()}</span><h1>${d.name}</h1><p>${d.ingredients.length} ингредиента · ${fmt(d.sales)} продаж за месяц · тренд ${d.trend>0?'+':''}${d.trend}%</p></div><div class="hero-kpis"><div><small>ЦЕНА</small><b>${money(price)}</b></div><div><small>СЕБЕСТОИМОСТЬ</small><b>${money(d.cost)}</b></div><div><small>МАРЖА</small><b>${margin}%</b></div></div></section>${tabs([['overview','Калькуляция'],['ingredients','Ингредиенты'],['sales','Продажи по точкам'],['history','История версии']],route().tab)}${route().tab==='ingredients'?dishIngredients(d):route().tab==='sales'?dishSales(d):route().tab==='history'?dishHistory(d):`<section class="grid equal"><article class="panel"><span class="kicker">ФАКТИЧЕСКАЯ КАЛЬКУЛЯЦИЯ</span><h2>Экономика порции</h2><div class="calc-grid"><div><small>Цена продажи</small><b>${money(price)}</b></div><div><small>Себестоимость</small><b class="${margin<60?'bad':''}">${money(d.cost)}</b></div><div><small>Валовая прибыль</small><b>${money(price-d.cost)}</b></div></div><div class="recommendation"><b>SHAFRAN AI: сценарий улучшения</b><p>${d.id==='d2'?'Лосось подорожал на 14%. Для возврата маржи к 60% повысьте цену до 9 600 ₸ либо уменьшите выход лосося на 20 г.':'Текущая калькуляция в целевом диапазоне. Потенциал роста — набор и допродажа напитка.'}</p><div class="form-row"><div class="field"><label>Новая цена, ₸</label><input id="scenarioPrice" type="number" value="${price}"></div><div class="field"><label>Себестоимость, ₸</label><input id="scenarioCost" type="number" value="${d.cost}"></div></div><p id="scenarioResult">Новая маржа: <b>${margin}%</b> · прибыль с порции: <b>${money(price-d.cost)}</b></p><button class="btn" data-action="calc-scenario">Пересчитать</button> <button class="btn-copper" data-action="save-price" data-id="${d.id}">Согласовать новую цену</button></div></article><article class="panel"><span class="kicker">СТРУКТУРА СЕБЕСТОИМОСТИ</span><h2>Ингредиенты</h2>${d.ingredients.map((a,i)=>{const x=D.stock.find(s=>s.id===a[0]);return `<div class="recipe-row"><div><b class="click" data-open="stock" data-id="${x.id}">${x.name}</b><small>${x.supplier}</small></div><div><small>Выход</small><b>${a[1]} ${x.unit}</b></div><div><small>Стоимость</small><b>${money(a[1]*x.price)}</b></div><button class="arrow" data-open="stock" data-id="${x.id}">→</button></div>`}).join('')}</article></section>`}`}
function dishIngredients(d){return `<article class="panel"><span class="kicker">СОСТАВ</span><h2>Технологическая карта</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Ингредиент</th><th>Брутто</th><th>Нетто</th><th>Цена единицы</th><th>Стоимость порции</th><th>Поставщик</th></tr></thead><tbody>${d.ingredients.map(a=>{const x=D.stock.find(s=>s.id===a[0]);return `<tr class="clickable" data-open="stock" data-id="${x.id}"><td><b>${x.name}</b></td><td>${(a[1]*1.08).toFixed(3)} ${x.unit}</td><td>${a[1]} ${x.unit}</td><td>${money(x.price)}</td><td>${money(a[1]*x.price)}</td><td>${x.supplier}</td></tr>`}).join('')}</tbody></table></div></article>`}
function dishSales(d){return `<article class="panel"><span class="kicker">ПРОДАЖИ</span><h2>${d.name} · по ресторанам</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Ресторан</th><th>Порций MTD</th><th>Выручка</th><th>Фактическая маржа</th><th>Возвраты</th></tr></thead><tbody>${D.restaurants.map((r,i)=>{const n=Math.round(d.sales/22*(.65+(i%7)/10));return `<tr class="clickable" data-open="restaurant" data-id="${r.id}" data-tab="sales"><td><b>${r.name}</b><br><small>${r.city}</small></td><td>${n}</td><td>${money(n*(state.prices[d.id]||d.price))}</td><td class="${i%8===2?'bad':'good'}">${Math.round((d.price-d.cost)/d.price*100)-(i%8===2?6:0)}%</td><td>${i%9===2?3:0}</td></tr>`}).join('')}</tbody></table></div></article>`}
function dishHistory(d){return `<section class="grid equal"><article class="panel"><span class="kicker">ВЕРСИИ</span><h2>История техкарты</h2><div class="timeline"><div class="timeline-item"><b>v12 · Себестоимость пересчитана</b><span>Сегодня 09:14 · автоматически по приходу сырья</span></div><div class="timeline-item"><b>v11 · Изменён выход</b><span>18 июля · Бренд-шеф · 220 → 210 г</span></div><div class="timeline-item"><b>v10 · Новая закупочная цена</b><span>04 июля · синхронизация iiko</span></div><div class="timeline-item"><b>v9 · Техкарта утверждена</b><span>21 июня · Айдар</span></div></div></article><article class="panel"><span class="kicker">АУДИТ</span><h2>Кто согласовал</h2><div class="compare"><div><small>Автор</small><b>Бренд-шеф</b></div><div><small>Финансы</small><b>Проверено</b></div><div><small>Закуп</small><b>Проверено</b></div><div><small>Статус</small><b class="good">Действует</b></div></div></article></section>`}
function renderFinance(){return pageHead('P&L В РЕАЛЬНОМ ВРЕМЕНИ','Финансы сети','От общего результата до ресторана, статьи, операции и первичного документа.','<button class="btn" data-action="budget">Бюджет / факт</button><button class="btn-dark" data-action="export">Скачать управленческий отчёт</button>')+`<section class="metrics">${metric('Выручка MTD','1,14 млрд ₸','↑ 11,2% год к году','dark',spark())}${metric('Валовая прибыль','487 млн ₸','42,7% от выручки')}${metric('Операционные расходы','318 млн ₸','↓ +3,8% к бюджету')}${metric('EBITDA','169 млн ₸','↑ 14,8% маржа')}</section><section class="grid equal"><article class="panel"><span class="kicker">УПРАВЛЕНЧЕСКИЙ P&L</span><h2>Расшифровка сети</h2><div class="table-wrap"><table class="data-table"><tbody>${[['Выручка',1140,'+11,2%'],['Себестоимость',-350,'+6,4%'],['Валовая прибыль',487,'+14,1%'],['ФОТ',-207,'+8,2%'],['Аренда и коммунальные',-68,'+2,1%'],['Маркетинг',-31,'−1,4%'],['Прочие OPEX',-79,'+4,5%'],['EBITDA',169,'+18,7%']].map(x=>`<tr class="clickable" data-action="finance-drill" data-label="${x[0]}"><td><b>${x[0]}</b></td><td class="${x[1]<0?'bad':'good'}">${Math.abs(x[1])} млн ₸</td><td>${x[2]}</td><td>→</td></tr>`).join('')}</tbody></table></div></article><article class="panel"><span class="kicker">ДИНАМИКА</span><h2>Денежный поток · 12 недель</h2><div class="chart">${[52,49,61,58,67,72,69,81,78,87,91,96].map((x,i)=>`<div><i style="height:${x}%"></i><span>${i+1}</span></div>`).join('')}</div></article></section><article class="panel"><span class="kicker">ПО РЕСТОРАНАМ</span><h2>Рейтинг EBITDA</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Ресторан</th><th>Выручка MTD</th><th>Валовая маржа</th><th>OPEX</th><th>EBITDA</th><th>План</th></tr></thead><tbody>${D.restaurants.map((r,i)=>`<tr class="clickable" data-open="restaurant" data-id="${r.id}" data-tab="finance"><td><b>${r.name}</b><br><small>${r.city}</small></td><td>${million(r.revenue*22)}</td><td>${(41+(i%5)*.8).toFixed(1)}%</td><td>${million(r.revenue*6)}</td><td class="${r.status==='risk'?'bad':'good'}">${(12+(i%7)*.7-(r.status==='risk'?3:0)).toFixed(1)}%</td><td>${r.plan}%</td></tr>`).join('')}</tbody></table></div></article>`}
function renderMarketing(){return pageHead('GROWTH CONTROL','Маркетинг и SMM','От рекламного расхода и публикации до брони, визита, чека и повторной покупки.','<button class="btn" data-action="content-plan">Контент-план</button><button class="btn-dark" data-action="new-campaign">+ Новая кампания</button>')+`<section class="metrics">${metric('Расход MTD','9,73 млн ₸','↓ 4,1% к бюджету')}${metric('Атрибутированная выручка','75,7 млн ₸','↑ ROAS 7,8')}${metric('Подтверждённые брони','5 660','↑ 13,4%')}${metric('Повторный визит','35,0%','↑ 4,2 п.п.')}</section><section class="grid equal"><article class="panel"><span class="kicker">ВОРОНКА ГОСТЯ</span><h2>Реклама → чек</h2>${[['Охват','4,8 млн',100],['Переходы','186 420',88],['Брони','9 814',76],['Визиты','8 907',64],['Повторный визит','3 116',52]].map(x=>`<div class="funnel" style="width:${x[2]}%"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</article><article class="panel"><span class="kicker">AI-КОНТЕНТ</span><h2>Публикации недели</h2><div class="timeline"><div class="timeline-item"><b>Сегодня 19:30 · Reels</b><span>Как готовим плов · Алматы · готово к публикации</span></div><div class="timeline-item"><b>Завтра 12:00 · Stories</b><span>Бизнес-ланч · вся сеть · ожидает согласования</span></div><div class="timeline-item"><b>05 августа 18:00 · Пост</b><span>Семейный ужин · Астана · черновик</span></div></div><button class="btn-copper" data-action="generate-content">Собрать контент на неделю</button></article></section><article class="panel"><div class="panel-head"><div><span class="kicker">КАМПАНИИ</span><h2>Эффективность до фактического визита</h2></div><button class="btn" data-action="export">Экспорт</button></div>${D.campaigns.map(c=>`<div class="campaign-row click" data-open="campaign" data-id="${c.id}"><div><b>${c.name}</b><small style="display:block;color:var(--muted)">${c.channel}</small></div><div><small>Расход</small><b>${money(c.spend)}</b></div><div><small>ROAS</small><b>${(c.revenue/c.spend).toFixed(1)}</b></div><div><small>Тренд</small><b class="${c.trend<0?'bad':'good'}">${c.trend>0?'+':''}${c.trend}%</b></div><button class="arrow">→</button></div>`).join('')}</article>`}
function campaignDetail(c){return `<section class="detail-hero"><div><span class="kicker">${c.channel} · CAMPAIGN ${c.id.toUpperCase()}</span><h1>${c.name}</h1><p>Атрибуция: рекламный клик → CRM-бронь → визит iiko → чек</p></div><div class="hero-kpis"><div><small>РАСХОД</small><b>${money(c.spend)}</b></div><div><small>ВЫРУЧКА</small><b>${money(c.revenue)}</b></div><div><small>ROAS</small><b>${(c.revenue/c.spend).toFixed(1)}</b></div></div></section>${tabs([['overview','Обзор'],['audience','Аудитории'],['content','Креативы'],['bookings','Брони и чеки']],route().tab)}${route().tab==='bookings'?campaignBookings(c):`<section class="grid equal"><article class="panel"><span class="kicker">СКВОЗНАЯ ВОРОНКА</span><h2>От показа до денег</h2>${[['Охват',fmt(c.reach),100],['Клики',fmt(Math.round(c.reach*.041)),84],['Брони',fmt(c.bookings),68],['Визиты',fmt(c.visits),56],['Повторный визит',fmt(Math.round(c.visits*.31)),44]].map(x=>`<div class="funnel" style="width:${x[2]}%"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</article><article class="panel"><span class="kicker">SHAFRAN AI</span><h2>${c.status==='risk'?'Кампания теряет эффективность':'Кампания в целевом диапазоне'}</h2><div class="compare"><div><small>CPL</small><b>${money(c.spend/c.bookings)}</b></div><div><small>Стоимость визита</small><b>${money(c.spend/c.visits)}</b></div><div><small>Средний чек</small><b>${money(c.revenue/c.visits)}</b></div><div><small>Повтор</small><b>31%</b></div></div><div class="recommendation"><b>Рекомендация</b><p>${c.status==='risk'?'Снизить бюджет на 30%, отключить аудиторию 45+ и перенести средства в CRM-реактивацию с ROAS 19,0.':'Увеличить бюджет на 15% при сохранении частоты не выше 3,2.'}</p><button class="btn-copper" data-action="campaign-decision">Принять рекомендацию</button> <button class="btn" data-action="create-campaign-task" data-id="${c.id}">Задача маркетологу</button></div></article></section>`}`}
function campaignBookings(c){return `<article class="panel"><span class="kicker">АТРИБУЦИЯ</span><h2>Брони, визиты и чеки</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Гость</th><th>Источник</th><th>Бронь</th><th>Ресторан</th><th>Статус</th><th>Чек</th></tr></thead><tbody>${['Айжан М.','Руслан К.','Динара А.','Марат С.','Сауле Н.','Ержан Т.'].map((n,i)=>`<tr><td><b>${n}</b></td><td>${c.channel}</td><td>BR-${8421+i}</td><td>${D.restaurants[i].name}</td><td>${i===4?statusTag('warn'):statusTag('ok')}</td><td>${i===4?'—':money(12400+i*860)}</td></tr>`).join('')}</tbody></table></div></article>`}
function renderTasks(){return pageHead('DECISION FLOW','Задачи и решения','AI находит отклонение, назначает ответственного и контролирует экономический эффект.','<button class="btn" data-action="task-board">Канбан</button><button class="btn-dark" data-action="new-task">+ Новая задача</button>')+`<section class="metrics">${metric('Открыто',state.tasks.filter(x=>x.status==='open').length,'3 критичных сегодня')}${metric('В работе',state.tasks.filter(x=>x.status==='progress').length,'назначены ответственные')}${metric('Закрыто за неделю',18,'↑ 4 к прошлой неделе')}${metric('Эффект решений','8,4 млн ₸','подтверждено финансами')}</section><article class="panel"><div class="panel-head"><div><span class="kicker">ЕДИНАЯ ОЧЕРЕДЬ</span><h2>Решения собственника и команды</h2></div><div class="filters"><button class="active">Все</button><button>Критично</button><button>Мои</button></div></div>${state.tasks.map(t=>`<div class="task-row click" data-open="task" data-id="${t.id}"><i class="${t.type==='Критично'?'risk':''}"></i><div><b>${t.title}</b><small>${t.source}</small></div><div><small>Ответственный</small><b>${t.owner}</b></div><div><small>Срок</small><b>${t.due}</b></div><span class="status-tag ${t.status==='done'?'ok':t.status==='progress'?'warn':'risk'}">${t.status==='done'?'Закрыта':t.status==='progress'?'В работе':'Открыта'}</span></div>`).join('')}</article>`}
function taskDetail(t){return `<span class="kicker">ЗАДАЧА ${t.id.toUpperCase()}</span><h2>${t.title}</h2><div class="compare"><div><small>Статус</small><b>${t.status==='done'?'Закрыта':t.status==='progress'?'В работе':'Открыта'}</b></div><div><small>Приоритет</small><b>${t.type}</b></div><div><small>Срок</small><b>${t.due}</b></div><div><small>Источник</small><b>SHAFRAN AI</b></div></div><div class="recommendation"><b>Почему создана задача</b><p>${t.source}. Система зафиксировала отклонение, рассчитала влияние и назначила действие по регламенту.</p></div><div class="field"><label>Ответственный</label><select id="taskOwner"><option>${t.owner}</option><option>Айдар</option><option>Региональный управляющий</option><option>Финансовый контролёр</option></select></div><div class="field" style="margin-top:10px"><label>Комментарий</label><textarea id="taskComment" placeholder="Добавить комментарий к решению"></textarea></div><div class="head-actions" style="margin-top:15px"><button class="btn" data-action="assign-task" data-id="${t.id}">В работу</button><button class="btn-copper" data-action="resolve-task" data-id="${t.id}">✓ Закрыть задачу</button></div><div class="timeline" style="margin-top:22px"><div class="timeline-item"><b>Задача создана AI</b><span>Сегодня · 11:42</span></div><div class="timeline-item"><b>Уведомлён ответственный</b><span>WhatsApp + внутренняя задача · 11:43</span></div></div>`}
function renderIntegrations(){return pageHead('DATA HUB','Интеграции','Единый контур данных без замены работающих систем: iiko, CRM, 1С, банки, реклама и AI.','<button class="btn" data-action="sync-all">Синхронизировать всё</button><button class="btn-dark" data-action="new-integration">+ Подключить источник</button>')+`<section class="metrics">${metric('Событий сегодня','26 542','↑ обработано без ошибок')}${metric('Источников','6','5 подключено · 1 ожидает')}${metric('Ошибок обмена','2','↓ повторная отправка')}${metric('Задержка данных','2 мин','в пределах SLA')}</section><article class="panel"><span class="kicker">КОНТУР ДАННЫХ</span><h2>Подключённые системы</h2>${D.integrations.map(i=>{const st=state.integrations[i.id]||i.status;return `<div class="integration-row click" data-open="integration" data-id="${i.id}"><span class="app-icon">${i.name.slice(0,2).toUpperCase()}</span><div><b>${i.name}</b><small style="display:block;color:var(--muted)">${i.scope}</small></div><span class="status-tag ${st==='connected'?'ok':'warn'}">${st==='connected'?'Подключено':'Ожидает доступа'}</span><div><small>Последний обмен</small><b>${i.last}</b></div><button class="arrow">→</button></div>`}).join('')}<div class="flow"><span>iiko · CRM · 1С · Банки · Реклама</span><b>→ SHAFRAN DATA HUB →</b><span>AI · Задачи · Решения</span></div></article>`}
function integrationDetail(i){const st=state.integrations[i.id]||i.status;return `<span class="kicker">ИНТЕГРАЦИЯ</span><h2>${i.name}</h2><div class="compare"><div><small>Статус</small><b>${st==='connected'?'Подключено':'Ожидает'}</b></div><div><small>Последний обмен</small><b>${i.last}</b></div><div><small>Событий сегодня</small><b>${fmt(i.events)}</b></div><div><small>Ошибок</small><b>${i.id==='onec'?2:0}</b></div></div><div class="recommendation"><b>Контур данных</b><p>${i.scope}. Обмен идёт через API/вебхуки с журналом ошибок и повторной доставкой.</p></div><div class="panel" style="padding:13px;margin-top:12px"><span class="kicker">ЖУРНАЛ ОБМЕНА</span><div class="timeline" style="margin-top:14px"><div class="timeline-item"><b>Пакет данных принят</b><span>${i.last} · 248 записей</span></div><div class="timeline-item"><b>Валидация завершена</b><span>Ошибок структуры нет</span></div><div class="timeline-item"><b>Агрегаты пересчитаны</b><span>Пульт сети и AI-сигналы обновлены</span></div></div></div><button class="${st==='connected'?'btn':'btn-copper'}" style="margin-top:14px" data-action="toggle-integration" data-id="${i.id}">${st==='connected'?'Переподключить':'Подключить сейчас'}</button>`}
function updateCrumbs(r){const parts=[`<button data-nav="dashboard">SHAFRAN</button>`,`<span>›</span>`,`<button data-nav="${r.s}">${routes[r.s]||'Раздел'}</button>`];if(r.id){let n='Карточка';if(r.s==='restaurants')n=D.restaurants.find(x=>x.id===r.id)?.name||n;if(r.s==='stock')n=D.stock.find(x=>x.id===r.id)?.name||n;if(r.s==='menu')n=D.dishes.find(x=>x.id===r.id)?.name||n;if(r.s==='marketing')n=D.campaigns.find(x=>x.id===r.id)?.name||n;parts.push('<span>›</span>',`<b>${n}</b>`)}crumbs.innerHTML=parts.join('')}
function render(){const r=route();document.querySelectorAll('#mainNav button').forEach(b=>b.classList.toggle('active',b.dataset.nav===r.s));updateCrumbs(r);let html='';if(r.s==='dashboard')html=renderDashboard();else if(r.s==='restaurants')html=r.id?restaurantDetail(D.restaurants.find(x=>x.id===r.id)||D.restaurants[0],r.tab):renderRestaurants();else if(r.s==='stock')html=r.id?stockDetail(D.stock.find(x=>x.id===r.id)||D.stock[0]):renderStock();else if(r.s==='menu')html=r.id?dishDetail(D.dishes.find(x=>x.id===r.id)||D.dishes[0]):renderMenu();else if(r.s==='finance')html=renderFinance();else if(r.s==='marketing')html=r.id?campaignDetail(D.campaigns.find(x=>x.id===r.id)||D.campaigns[0]):renderMarketing();else if(r.s==='tasks')html=renderTasks();else if(r.s==='integrations')html=renderIntegrations();else html=renderDashboard();view.innerHTML=html;view.focus({preventScroll:true});badges()}
function toast(t){const x=document.getElementById('toast');x.querySelector('span').textContent=t;x.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.classList.remove('show'),2600)}
function openDrawer(html){drawerBody.innerHTML=html;drawer.classList.add('open');overlay.classList.add('open')}
function closeDrawer(){drawer.classList.remove('open');overlay.classList.remove('open')}
function openModal(html){modalBody.innerHTML=html;modal.classList.add('open')}
function closeModal(){modal.classList.remove('open')}
function taskModal(prefill=''){openModal(`<span class="kicker">НОВАЯ ЗАДАЧА</span><h2>Поставить задачу</h2><div class="field"><label>Задача</label><input id="newTaskTitle" value="${prefill}"></div><div class="form-row" style="margin-top:10px"><div class="field"><label>Ответственный</label><select id="newTaskOwner"><option>Региональный управляющий</option><option>Руководитель снабжения</option><option>Бренд-шеф</option><option>Финансовый контролёр</option><option>Head of Marketing</option></select></div><div class="field"><label>Срок</label><input id="newTaskDue" value="Сегодня · 18:00"></div></div><div class="field" style="margin-top:10px"><label>Описание</label><textarea id="newTaskText" placeholder="Ожидаемый результат и комментарий"></textarea></div><button class="btn-copper" style="margin-top:14px" data-action="save-new-task">Создать и уведомить</button>`) }
function searchModal(){const all=[...D.restaurants.map(x=>['Ресторан',x.name,'restaurants',x.id]),...D.stock.map(x=>['Товар',x.name,'stock',x.id]),...D.dishes.map(x=>['Блюдо',x.name,'menu',x.id]),...D.campaigns.map(x=>['Кампания',x.name,'marketing',x.id])];openModal(`<span class="kicker">ГЛОБАЛЬНЫЙ ПОИСК</span><h2>Найти в системе</h2><div class="field"><input id="globalSearch" autofocus placeholder="Ресторан, товар, блюдо, кампания…"></div><div class="search-results" id="globalResults" style="margin-top:10px">${all.slice(0,8).map(x=>`<button class="search-result" data-navto="${x[2]}" data-id="${x[3]}"><small>${x[0]}</small><b>${x[1]}</b><span>→</span></button>`).join('')}</div>`);const inp=document.getElementById('globalSearch'),out=document.getElementById('globalResults');inp.focus();inp.oninput=()=>{const q=inp.value.toLowerCase();out.innerHTML=all.filter(x=>x[1].toLowerCase().includes(q)).slice(0,12).map(x=>`<button class="search-result" data-navto="${x[2]}" data-id="${x[3]}"><small>${x[0]}</small><b>${x[1]}</b><span>→</span></button>`).join('')}}
function handleAction(a,el){const id=el.dataset.id;if(a==='close-drawer')closeDrawer();else if(a==='close-modal')closeModal();else if(a==='search')searchModal();else if(a==='profile')openDrawer(`<span class="kicker">ПРОФИЛЬ</span><h2>Айдар · Владелец сети</h2><div class="compare"><div><small>Роль</small><b>Собственник</b></div><div><small>Доступ</small><b>Полный</b></div><div><small>Ресторанов</small><b>22</b></div><div><small>AI-решений</small><b>18</b></div></div><div class="recommendation"><b>Режим демонстрации</b><p>Все данные вымышлены и показывают целевую архитектуру системы.</p></div>`);else if(a==='new-task')taskModal();else if(a==='save-new-task'){const title=document.getElementById('newTaskTitle').value.trim();if(!title)return toast('Введите название задачи');state.tasks.unshift({id:'t'+Date.now(),title,type:'Ручная',owner:document.getElementById('newTaskOwner').value,due:document.getElementById('newTaskDue').value,status:'open',source:'Создана Айдаром'});save();closeModal();toast('Задача создана, ответственный уведомлён');render()}else if(a==='approve-order'){state.orders[id]=true;save();toast('Заявка согласована и отправлена поставщику');render()}else if(a==='transfer-item')openModal(`<span class="kicker">ПЕРЕМЕЩЕНИЕ</span><h2>Переместить остаток</h2><div class="form-row"><div class="field"><label>Откуда</label><select><option>Шафран · MEGA</option><option>Центральный склад</option></select></div><div class="field"><label>Куда</label><select><option>Шафран · Туран</option><option>Шафран · Арбат</option></select></div></div><div class="field" style="margin-top:10px"><label>Количество</label><input value="18 кг"></div><button class="btn-copper" style="margin-top:13px" data-action="confirm-transfer">Создать перемещение</button>`);else if(a==='confirm-transfer'){closeModal();toast('Перемещение создано · склад и логистика уведомлены')}else if(a==='calc-scenario'){const p=+document.getElementById('scenarioPrice').value,c=+document.getElementById('scenarioCost').value,m=Math.round((p-c)/p*100);document.getElementById('scenarioResult').innerHTML=`Новая маржа: <b>${m}%</b> · прибыль с порции: <b>${money(p-c)}</b>`}else if(a==='save-price'){state.prices[id]=+document.getElementById('scenarioPrice').value;save();toast('Новая цена согласована · будет передана в iiko');render()}else if(a==='assign-task'||a==='resolve-task'){const t=state.tasks.find(x=>x.id===id);if(t){t.status=a==='resolve-task'?'done':'progress';save();closeDrawer();toast(a==='resolve-task'?'Задача закрыта, эффект отправлен на проверку':'Задача принята в работу');render()}}else if(a==='toggle-integration'){state.integrations[id]='connected';save();closeDrawer();toast('Интеграция подключена, начата первичная синхронизация');render()}else if(a==='create-restaurant-task')taskModal('Проверить отклонения ресторана');else if(a==='create-campaign-task')taskModal('Оптимизировать рекламную кампанию');else if(a==='finance-drill')openDrawer(`<span class="kicker">ФИНАНСОВАЯ РАСШИФРОВКА</span><h2>${el.dataset.label}</h2><div class="compare"><div><small>Факт</small><b>31,8 млн ₸</b></div><div><small>Бюджет</small><b>29,4 млн ₸</b></div><div><small>Отклонение</small><b class="bad">+8,2%</b></div><div><small>Документов</small><b>184</b></div></div><div class="timeline" style="margin-top:20px"><div class="timeline-item"><b>iiko · смены ресторанов</b><span>82 операции · 18,4 млн ₸</span></div><div class="timeline-item"><b>1С · начисления</b><span>54 документа · 9,7 млн ₸</span></div><div class="timeline-item"><b>Банк · фактические платежи</b><span>48 операций · 3,7 млн ₸</span></div></div><button class="btn" data-action="export">Скачать расшифровку</button>`);else if(['export','sync-iiko','sync-all','campaign-decision','generate-content','content-plan','inventory','supplier-message','request-quote','reply-review','new-order','transfers','budget','compare','task-board','new-campaign','new-integration','new-dish'].includes(a))toast({'export':'Отчёт сформирован','sync-iiko':'Данные iiko синхронизированы','sync-all':'Все источники синхронизированы','campaign-decision':'Рекомендация принята, бюджет обновлён','generate-content':'AI подготовил контент-план на 7 дней','content-plan':'Контент-план открыт','inventory':'Инвентаризация создана','supplier-message':'Открыт диалог с поставщиком','request-quote':'Запрос цены отправлен','reply-review':'Ответ подготовлен AI','new-order':'Черновик заявки создан','transfers':'Открыт журнал перемещений','budget':'Открыт сценарий бюджет/факт','compare':'Выбраны 4 ресторана для сравнения','task-board':'Режим канбан включён','new-campaign':'Создан черновик кампании','new-integration':'Открыт мастер подключения','new-dish':'Создана новая техкарта'}[a]);else if(a==='period')toast('Период изменяется во всех показателях одновременно')}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return}const to=e.target.closest('[data-navto]');if(to){closeModal();go(to.dataset.navto,to.dataset.id);return}const open=e.target.closest('[data-open]');if(open){const type=open.dataset.open,id=open.dataset.id,tab=open.dataset.tab;go(type==='restaurant'?'restaurants':type==='dish'?'menu':type==='campaign'?'marketing':type,id,tab);return}const tab=e.target.closest('[data-tab]');if(tab){const r=route();go(r.s,r.id,tab.dataset.tab);return}const a=e.target.closest('[data-action]');if(a){handleAction(a.dataset.action,a);return}});overlay.onclick=closeDrawer;window.onpopstate=render;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if(e.key==='Escape'){closeDrawer();closeModal()}});badges();render();
})();
